/**
 * Planted test set for the redactor: 200 generated, fake items.
 *
 * Everything here is synthetic. No real person, mailbox, phone line, card
 * account or street is used:
 * - emails use reserved domains (example.com, example.org, example.net, .test)
 * - phones use the fictional 555-01xx block, plus the UK and Australian
 *   ranges reserved for drama and fiction
 * - card numbers start from documented test-card prefixes, then take random
 *   digits and a computed Luhn check digit. They are not real accounts.
 * - streets use made-up names
 *
 * The mix of variants was fixed before the redactor existed. It includes
 * some formats a simple rule set is expected to miss (obfuscated emails,
 * spelled-out phone numbers, streets with no suffix). Those are kept on
 * purpose so the report shows real misses. Do not edit this file to raise a
 * score.
 */

export type PlantedType = "email" | "phone" | "card" | "address";

export type PlantedItem = {
  id: string;
  type: PlantedType;
  /** Format label, used to explain misses. */
  variant: string;
  /** Sentence containing the planted value exactly once. */
  text: string;
  /** The planted fake value. */
  value: string;
};

export const PLANTED_TYPES: readonly PlantedType[] = [
  "email",
  "phone",
  "card",
  "address",
];

export const ITEMS_PER_TYPE = 50;

/** Small deterministic PRNG so the set is identical on every run. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

type Rng = {
  int: (min: number, max: number) => number;
  pick: <T>(items: readonly T[]) => T;
  digits: (n: number) => string;
};

function makeRng(seed: number): Rng {
  const next = mulberry32(seed);
  const int = (min: number, max: number) =>
    min + Math.floor(next() * (max - min + 1));
  return {
    int,
    pick: <T,>(items: readonly T[]) => items[int(0, items.length - 1)],
    digits: (n: number) =>
      Array.from({ length: n }, () => String(int(0, 9))).join(""),
  };
}

/** Appends the Luhn check digit to a digit string. */
function withLuhnCheckDigit(body: string): string {
  let sum = 0;
  let double = true;
  for (let i = body.length - 1; i >= 0; i--) {
    let d = Number(body[i]);
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }
  return body + String((10 - (sum % 10)) % 10);
}

function repeatVariant<T>(
  entries: ReadonlyArray<readonly [string, number, (r: Rng) => string]>,
  rng: Rng,
): Array<{ variant: string; value: string }> {
  const out: Array<{ variant: string; value: string }> = [];
  for (const [variant, count, make] of entries) {
    for (let i = 0; i < count; i++) out.push({ variant, value: make(rng) });
  }
  return out;
}

const FIRST = ["jane", "sam", "alex", "riley", "casey", "morgan", "taylor", "jordan"];
const LAST = ["doe", "roe", "tester", "sample", "fakeman", "nobody", "placeholder"];
const DOMAINS = ["example.com", "example.org", "example.net", "mail.example.com", "corp.example.org"];
const ATTACH = ["test", "invalid"];

function emailItems(rng: Rng) {
  const local = (r: Rng) => `${r.pick(FIRST)}.${r.pick(LAST)}`;
  return repeatVariant(
    [
      ["plain", 20, (r) => `${local(r)}@${r.pick(DOMAINS.slice(0, 3))}`],
      ["plus-tag", 8, (r) => `${r.pick(FIRST)}+${r.pick(ATTACH)}${r.int(1, 99)}@${r.pick(DOMAINS.slice(0, 3))}`],
      ["subdomain", 6, (r) => `${local(r)}@mail.${r.pick(["example.com", "example.org"])}`],
      ["hyphen-underscore", 6, (r) => `${r.pick(FIRST)}_${r.pick(LAST)}-${r.int(1, 99)}@${r.pick(DOMAINS.slice(0, 3))}`],
      ["uppercase", 4, (r) => `${r.pick(FIRST)}.${r.pick(LAST)}@${r.pick(["EXAMPLE.COM", "EXAMPLE.ORG"])}`.toUpperCase()],
      ["obfuscated-at-dot", 6, (r) => `${r.pick(FIRST)}${r.int(1, 99)} at ${r.pick(["example", "sample"])} dot com`],
    ],
    rng,
  );
}

function phoneItems(rng: Rng) {
  const area = (r: Rng) => r.pick(["202", "415", "212", "312", "646", "720"]);
  const line = (r: Rng) => `01${r.int(0, 9)}${r.int(0, 9)}`;
  return repeatVariant(
    [
      ["dashes", 10, (r) => `${area(r)}-555-${line(r)}`],
      ["parens", 10, (r) => `(${area(r)}) 555-${line(r)}`],
      ["dots", 6, (r) => `${area(r)}.555.${line(r)}`],
      ["spaces", 4, (r) => `${area(r)} 555 ${line(r)}`],
      ["plus1", 5, (r) => `+1 ${area(r)} 555 ${line(r)}`],
      ["bare-10-digits", 4, (r) => `${area(r)}555${line(r)}`],
      ["extension", 3, (r) => `${area(r)}-555-${line(r)} ext. ${r.int(10, 999)}`],
      ["intl-uk", 4, (r) => `+44 20 7946 0${r.int(100, 999)}`],
      ["intl-au", 2, (r) => `+61 2 5550 ${line(r)}`],
      ["spelled-out", 2, () => "two zero two five five five zero one four three"],
    ],
    rng,
  );
}

function cardItems(rng: Rng) {
  const group4 = (s: string) => s.match(/.{1,4}/g)!.join(" ");
  const group4dash = (s: string) => s.match(/.{1,4}/g)!.join("-");
  const sixteen = (r: Rng, prefix: string) =>
    withLuhnCheckDigit(prefix + r.digits(15 - prefix.length));
  const amex = (r: Rng) => withLuhnCheckDigit("378282" + r.digits(8));
  return repeatVariant(
    [
      ["visa-spaces", 12, (r) => group4(sixteen(r, "400000"))],
      ["visa-dashes", 10, (r) => group4dash(sixteen(r, "400000"))],
      ["no-separators", 10, (r) => sixteen(r, r.pick(["400000", "555555", "601111"]))],
      ["amex-4-6-5", 8, (r) => {
        const n = amex(r);
        return `${n.slice(0, 4)} ${n.slice(4, 10)} ${n.slice(10)}`;
      }],
      ["mastercard-spaces", 5, (r) => group4(sixteen(r, "555555"))],
      ["discover-dashes", 5, (r) => group4dash(sixteen(r, "601111"))],
    ],
    rng,
  );
}

const STREETS = ["Maple", "Cedar Hollow", "Fakeland", "Sample", "Placeholder", "Willow Test", "Imaginary"];

function addressItems(rng: Rng) {
  const num = (r: Rng) => r.int(1, 9999);
  const name = (r: Rng) => r.pick(STREETS);
  return repeatVariant(
    [
      ["full-suffix", 12, (r) => `${num(r)} ${name(r)} ${r.pick(["Street", "Avenue", "Road", "Boulevard", "Drive", "Lane", "Court", "Place"])}`],
      ["abbreviated", 8, (r) => `${num(r)} ${name(r)} ${r.pick(["St", "Ave", "Rd", "Blvd", "Dr", "Ln", "Ct", "Pl"])}`],
      ["abbrev-period", 4, (r) => `${num(r)} ${name(r)} ${r.pick(["St.", "Ave.", "Rd.", "Blvd."])}`],
      ["with-unit", 6, (r) => `${num(r)} ${name(r)} Street, ${r.pick(["Apt", "Suite", "Unit"])} ${r.int(1, 40)}${r.pick(["", "B", "C"])}`],
      ["directional", 4, (r) => `${num(r)} ${r.pick(["N", "South", "W", "East"])} ${name(r)} Avenue`],
      ["ordinal-street", 4, (r) => `${num(r)} ${r.pick(["5th", "42nd", "3rd", "11th"])} Street`],
      ["po-box", 4, (r) => `${r.pick(["PO Box", "P.O. Box"])} ${r.int(10, 99999)}`],
      ["lowercase", 3, (r) => `${num(r)} ${name(r).toLowerCase()} ${r.pick(["street", "ave", "road"])}`],
      ["no-suffix", 2, (r) => `${num(r)} Broadway`],
      ["route-no-suffix", 2, (r) => `${r.int(100, 999)} Route ${r.int(1, 99)}`],
      ["suffix-in-middle", 1, (r) => `${num(r)} County Road ${r.int(1, 99)}`],
    ],
    rng,
  );
}

const TEMPLATES: Record<PlantedType, readonly string[]> = {
  email: [
    "You can reach me at {v} if you have questions.",
    "Please send the receipt to {v} when ready.",
    "My contact is {v} and I check it daily.",
    "Reply to {v} with the details.",
  ],
  phone: [
    "Call me on {v} after lunch.",
    "My number is {v} if the delivery is late.",
    "Text {v} when you arrive.",
    "The best way to reach me is {v} on weekdays.",
  ],
  card: [
    "I paid with the card {v} last week.",
    "The charge on {v} looked wrong to me.",
    "Use {v} for the refund please.",
    "My card number is {v} and it expires soon.",
  ],
  address: [
    "Please ship it to {v} this time.",
    "I moved and now live at {v} in the new place.",
    "The package went to {v} by mistake.",
    "Deliver to {v} before Friday.",
  ],
};

/** Builds the 200 planted items: 50 per type, identical on every run. */
export function generatePlanted(seed = 20260101): PlantedItem[] {
  const rng = makeRng(seed);
  const builders: Record<PlantedType, (r: Rng) => Array<{ variant: string; value: string }>> = {
    email: emailItems,
    phone: phoneItems,
    card: cardItems,
    address: addressItems,
  };
  const items: PlantedItem[] = [];
  for (const type of PLANTED_TYPES) {
    const entries = builders[type](rng);
    entries.forEach((entry, i) => {
      const template = TEMPLATES[type][i % TEMPLATES[type].length];
      items.push({
        id: `${type}-${String(i + 1).padStart(2, "0")}`,
        type,
        variant: entry.variant,
        text: template.replace("{v}", entry.value),
        value: entry.value,
      });
    });
  }
  return items;
}

export type Finding = { type: string; start: number; end: number };
export type RedactFn = (text: string) => { findings: readonly Finding[] };

export type TypeScore = { type: PlantedType; total: number; caught: number; missed: number };
export type MissedItem = { id: string; type: PlantedType; variant: string; value: string; reason: "not-detected" | "partial" };
export type Evaluation = { scores: TypeScore[]; missed: MissedItem[] };

/**
 * An item counts as caught only when a finding of the expected type covers
 * the whole planted value. A finding that covers only part of it leaves some
 * of the value readable, so it counts as missed (reason "partial").
 */
export function evaluatePlanted(items: readonly PlantedItem[], redact: RedactFn): Evaluation {
  const scores = new Map<PlantedType, TypeScore>(
    PLANTED_TYPES.map((t) => [t, { type: t, total: 0, caught: 0, missed: 0 }]),
  );
  const missed: MissedItem[] = [];
  for (const item of items) {
    const score = scores.get(item.type)!;
    score.total++;
    const start = item.text.indexOf(item.value);
    const end = start + item.value.length;
    const { findings } = redact(item.text);
    const sameType = findings.filter((f) => f.type === item.type);
    const covered = sameType.some((f) => f.start <= start && f.end >= end);
    if (covered) {
      score.caught++;
      continue;
    }
    score.missed++;
    const overlaps = sameType.some((f) => f.start < end && f.end > start);
    missed.push({
      id: item.id,
      type: item.type,
      variant: item.variant,
      value: item.value,
      reason: overlaps ? "partial" : "not-detected",
    });
  }
  return { scores: [...scores.values()], missed };
}
